from collections import deque

def itineraire(graphe, depart, arrivee):
    parent = {depart: None}
    file = deque([depart])
    while file:
        ville = file.popleft()
        for voisin in graphe[ville]:
            if voisin not in parent:
                parent[voisin] = ville
                file.append(voisin)
    if arrivee not in parent:
        return None
    chemin = []
    ville = arrivee
    while ville is not None:
        chemin.append(ville)
        ville = parent[ville]
    return chemin[::-1]

