def ordre_cours(prerequis):
    restants = {cours: len(p) for cours, p in prerequis.items()}
    ordre = []
    while len(ordre) < len(prerequis):
        prets = sorted(c for c, n in restants.items() if n == 0 and c not in ordre)
        if not prets:
            return None
        cours = prets[0]
        ordre.append(cours)
        for autre, p in prerequis.items():
            if cours in p:
                restants[autre] -= 1
    return ordre

