            continue
        for voisin, km in graphe[ville].items():
            nouvelle = d + km
            if voisin not in dist or nouvelle < dist[voisin]:
                dist[voisin] = nouvelle
                heapq.heappush(tas, (nouvelle, voisin))
    return dist

import heapq

def itineraire(graphe, depart, arrivee):
    dist = {depart: 0}
    parent = {depart: None}
    tas = [(0, depart)]
    while tas:
        d, ville = heapq.heappop(tas)
        if d > dist[ville]:
            continue
        for voisin, km in graphe[ville].items():
            nouvelle = d + km
            if voisin not in dist or nouvelle < dist[voisin]:
                dist[voisin] = nouvelle
                parent[voisin] = ville
                heapq.heappush(tas, (nouvelle, voisin))
    if arrivee not in dist:
        return None
    chemin = []
    ville = arrivee
    while ville is not None:
        chemin.append(ville)
        ville = parent[ville]
    return [dist[arrivee], chemin[::-1]]
